import {
  CollaborationMessageSchema,
  CollaborationViewSchema,
  COLLABORATION_EXECUTION_DISABLED,
} from '@mitzo/protocol';
export const uuid = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
export const settings = {
  binding: {
    version: 2,
    account: { accountId: 'same-offline-account', provider: 'openai-codex', profileRevision: 'r1' },
    harness: { implementation: 'codex' },
    execution: { location: 'local', targetId: 'mac', targetRevision: 'r1' },
  },
  selection: {
    version: 1,
    agent: { profileId: 'default', revision: 1 },
    context: { source: 'none', revision: null },
    permission: { mode: 'agent', revision: 0 },
    model: 'offline-fixture',
    thinking: null,
  },
  repositoryWorkspaceId: 'synthetic-workspace',
};
export const sharedPrompt = CollaborationMessageSchema.parse({
  version: 1,
  messageId: uuid(2),
  projectionId: uuid(3),
  sequence: 1,
  author: 'operator',
  source: null,
  replyToDeliveryId: null,
  text: 'Review this design together.',
  membershipRevision: 1,
  policySequence: 0,
  policyRevisions: { architect: 0, reviewer: 0, reader: 0 },
  responders: ['architect', 'reviewer'],
  readers: ['architect', 'reviewer', 'reader'],
  snapshot: null,
  settings: { architect: settings, reviewer: settings, reader: settings },
  deliveries: [
    {
      version: 1,
      deliveryId: uuid(4),
      sessionId: 'architect',
      purpose: 'reply',
      revision: 1,
      status: 'delivered',
      commandId: 'ordinary-architect',
      reason: null,
    },
    {
      version: 1,
      deliveryId: uuid(5),
      sessionId: 'reviewer',
      purpose: 'reply',
      revision: 1,
      status: 'uncertain',
      commandId: 'ordinary-reviewer',
      reason: 'Awaiting the original owner. Do not resend.',
    },
    {
      version: 1,
      deliveryId: uuid(6),
      sessionId: 'reader',
      purpose: 'context',
      revision: 0,
      status: 'pending',
      commandId: null,
      reason: null,
    },
  ],
});
export const sharedReply = CollaborationMessageSchema.parse({
  ...sharedPrompt,
  messageId: uuid(7),
  projectionId: uuid(8),
  sequence: 2,
  author: { sessionId: 'architect' },
  source: {
    conversationId: 'architect',
    commandId: 'ordinary-architect',
    messageId: 'final-answer',
    blockIds: ['text'],
    throughSequence: 20,
  },
  replyToDeliveryId: uuid(4),
  text: 'Architect answer is retained even while Reviewer is uncertain.',
  responders: [],
  readers: [],
  settings: {},
  deliveries: [],
});
export function sharedConversationView() {
  return CollaborationViewSchema.parse({
    version: 1,
    collaborationId: uuid(1),
    membershipRevision: 1,
    participantSessionIds: ['architect', 'reviewer', 'reader'],
    unavailableParticipantSessionIds: [],
    cursor: 2,
    policySequence: 0,
    policies: ['architect', 'reviewer', 'reader'].map((sessionId) => ({
      version: 1,
      sessionId,
      revision: 0,
      membershipRevision: 1,
      effectiveFromSequence: 0,
      readsFutureDiscussion: sessionId === 'reader',
      repliesByDefault: sessionId === 'architect',
    })),
    messages: [sharedPrompt, sharedReply],
    hasEarlierMessages: false,
    joins: [],
    execution: COLLABORATION_EXECUTION_DISABLED,
  });
}
